import { cn } from "@hunt/styled-ui";
import { LockKeyhole } from "lucide-react";
import React from "react";
import { type GachaPuzzle, type TopBannerDisplay } from "../types";

type GachaTopbarItemProps = {
  onClick: () => void;
  state: TopBannerDisplay;
  selected?: boolean;
};

function GachaTopbarItem({ selected, onClick, state }: GachaTopbarItemProps) {
  const isLocked = state.state === "locked";

  return (
    <button
      type="button"
      className={cn(
        "flex flex-col gap-2 text-center items-center px-6 py-2 rounded-md bg-white border border-neutral-400",
        isLocked ? "px-4 brightness-50" : "hover:bg-neutral-300",
        selected && "shadow-md border-black hover:bg-white",
      )}
      onClick={isLocked ? undefined : onClick}
      disabled={isLocked}
    >
      <div className={cn(isLocked && "cursor-not-allowed")}>
        <div
          className={cn(
            "text-neutral-500 text-lg font-bold",
            selected && !isLocked && "text-black",
            isLocked && "text-neutral-400",
          )}
        >
          {state ? (
            <div className="flex gap-2 items-center">
              {isLocked && <LockKeyhole />}
              <div className="flex flex-col gap-1.5">{state.name}</div>
            </div>
          ) : (
            <div>Loading...</div>
          )}
        </div>
      </div>
    </button>
  );
}

type GachaTopbarProps = {
  banners: TopBannerDisplay[];
  selectedBanner: string | null;
  onBannerSelect: (bannerSlug: string) => void;
  meta?: GachaPuzzle | null;
};

const HOURLY_STATE: TopBannerDisplay = {
  slug: "hourlies",
  state: "unlocked",
  name: "Hourlies",
};

function GachaTopbar({
  banners,
  selectedBanner,
  onBannerSelect,
  meta,
}: GachaTopbarProps) {
  const metaName = meta ? meta.title || "Meta" : "???";
  const metaState: TopBannerDisplay = {
    slug: "meta",
    name: metaName,
    state: meta ? (meta.state ?? "locked") : "locked",
  };

  return (
    <div className="flex justify-end my-2">
      <div
        className="w-fit flex flex-row gap-2 items-center flex-wrap"
        data-tutorial="quests"
      >
        {banners.map((banner) => (
          <GachaTopbarItem
            key={banner.slug}
            state={banner}
            onClick={() => {
              onBannerSelect(banner.slug);
            }}
            selected={selectedBanner === banner.slug}
          />
        ))}
        <GachaTopbarItem
          key="hourlies"
          state={HOURLY_STATE}
          onClick={() => {
            onBannerSelect("hourlies");
          }}
          selected={selectedBanner === "hourlies"}
        />
        {metaState && (
          <GachaTopbarItem
            key="meta"
            state={metaState}
            onClick={() => {
              onBannerSelect("meta");
            }}
            selected={selectedBanner === "meta"}
          />
        )}
      </div>
    </div>
  );
}

export default GachaTopbar;
