import { CopyToClipboard } from "@hunt/copy-to-clipboard";
import {
  type TeamHuntState,
  type TeamInfo,
  type QuestSchema,
} from "@hunt/public-client";
import { ExclamationMark } from "@hunt/puzzle-components";
import { PrimarySearchField } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { type ParsedQs } from "qs";
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { type z } from "zod";
import canonicalizeInput from "../../../../../lib/canonicalizeInput";
import { ErratumIcon } from "../../../components/ErratumIcon";
import { SubpuzzleGuessSection } from "../../../components/PuzzleGuessSection";
import { TeamStateProvider } from "../../../components/TeamStateProvider";
import { updateQueryParam } from "../../../rounds/query_param_utils";
import { IS_STATIC_SITE } from "../../../utils/staticSite";
import casino_chip from "./assets/casino_chip.svg";
import {
  GachaActionButton,
  GachaActionLink,
} from "./components/GachaActionButton";
import GachaBackButton from "./components/GachaBackButton";
import GachaCountdown from "./components/GachaCountdown";
import GachaTopbar from "./components/GachaTopbar";
import PullInfo from "./components/PullInfo";
import TopGuessesPie from "./components/TopGuessesPie";
import {
  PULL_COST_MULTIPLIER,
  HOURLIES_PULL_GAINS,
  KNOWLEDGE_CHECKS_PULL_GAINS,
} from "./constants";
import {
  CASINO_BACKGROUND_STYLE,
  YELLOW_GRADIENT_STYLING,
} from "./gacha_styling";
import GachaTutorial from "./tutorial/GachaTutorial";
import type { CasinoStateWithUI } from "./types";
import useGachaQueryParams, { GACHA_QUERY_KEYS } from "./useGachaQueryParam";

type Quest = z.infer<typeof QuestSchema>;
type Guesses = Quest["guesses"];
const QUEST_RATE_LIMIT_MS = 30_000;

const GachaQuests = ({
  state,
  teamState,
  teamInfo,
  queryParams,
  numChips,
  nextQuestUnlockTime,
  topGuessPercentages,
  questContentMap,
  questContentNodeMap,
  questContentCopyableMap,
  onLocalQuestSubmit,
  onAddPulls,
  onResetRound,
}: {
  state: CasinoStateWithUI;
  teamState: TeamHuntState;
  teamInfo: TeamInfo;
  queryParams?: ParsedQs | URLSearchParams;
  numChips: number;
  nextQuestUnlockTime: Date | undefined;
  topGuessPercentages?: Record<
    string,
    { input: string; percentage: number }[] | undefined
  >;
  questContentMap?: Record<string, string>;
  questContentNodeMap?: Record<string, React.ReactNode>;
  questContentCopyableMap?: Record<string, boolean>;
  onLocalQuestSubmit?: (args: {
    bannerSlug: string;
    questSlug: string;
    guess: string;
  }) => Promise<{ error?: string; canonicalInput?: string; solved?: boolean }>;
  onAddPulls?: (pullCount: number) => void;
  onResetRound?: () => void;
}) => {
  const { banner } = useGachaQueryParams(queryParams);
  const [selectedBannerSlug, setSelectedBannerSlug] = useState(banner);
  const [selectedQuestSlug, setSelectedQuestSlug] = useState<string>();
  const [questContent, setQuestContent] = useState<React.ReactNode | null>(
    null,
  );
  const [loadingQuestContent, setLoadingQuestContent] = useState(false);
  const [localGuessInput, setLocalGuessInput] = useState("");
  const [localGuessError, setLocalGuessError] = useState<string | null>(null);
  const [localGuessSubmitting, setLocalGuessSubmitting] = useState(false);
  const [localPullInput, setLocalPullInput] = useState("1");
  const [rateLimitUntilByQuest, setRateLimitUntilByQuest] = useState<
    Record<string, number>
  >({});
  const rateLimitTimeoutsRef = useRef<Map<string, number>>(new Map());

  const [guesses, setGuesses] = useState<Guesses>([]);

  const [hourlyInput, setHourlyInput] = useState<Record<string, string>>(() => {
    const initialHourlyInputs: Record<string, string> = {};
    if (state.quests) {
      state.quests
        .filter((quest) => quest.banner_slug === "hourlies")
        .forEach((quest) => {
          if (quest.guesses.length > 0) {
            initialHourlyInputs[quest.quest_slug] =
              quest.guesses[0].canonical_input;
          }
        });
    }
    return initialHourlyInputs;
  });
  const initialReferencedCluesRef = useRef<Record<string, string[]>>({});
  const [questUpdates, setQuestUpdates] = useState<Set<string>>(new Set());

  const banners = useMemo(() => {
    return state.banners || [];
  }, [state.banners]);

  const availableBannerSlugs = useMemo(() => {
    const slugs = banners.map((banner) => banner.slug);
    if (state.meta?.state === "unlocked") {
      slugs.push("meta");
    }
    slugs.push("hourlies");
    return slugs;
  }, [banners, state.meta?.state]);

  const quests = useMemo(() => {
    return state.quests || [];
  }, [state.quests]);

  const referencedClues = useMemo(() => {
    return quests.reduce<Record<string, string[]>>((acc, quest) => {
      acc[quest.quest_slug] = quest.referenced_clues || [];
      return acc;
    }, {});
  }, [quests]);

  const currentQuests: Quest[] = useMemo(() => {
    if (!selectedBannerSlug) return [];
    return quests?.filter((quest) => quest.banner_slug === selectedBannerSlug);
  }, [selectedBannerSlug, quests]);

  const currentQuestSlugs = useMemo(() => {
    return currentQuests.map((quest) => quest.quest_slug);
  }, [currentQuests]);

  const prevQuestSlugsRef = useRef<string[]>([]);
  const questSlugsChanged = useMemo(() => {
    const current = currentQuestSlugs;
    const prev = prevQuestSlugsRef.current;
    const changed =
      current.length !== prev.length ||
      current.some((slug, i) => slug !== prev[i]);
    if (changed) {
      prevQuestSlugsRef.current = current;
    }
    return changed;
  }, [currentQuestSlugs]);

  const currentQuest: Quest | undefined = useMemo(() => {
    return currentQuests.find(
      (quest) => quest.quest_slug === selectedQuestSlug,
    );
  }, [currentQuests, selectedQuestSlug]);

  useEffect(() => {
    const storageKey = `fates_thread_casino_referenced_clues_${teamInfo.teamUsername}`;
    try {
      const raw =
        typeof window !== "undefined" ? localStorage.getItem(storageKey) : null;
      if (raw) {
        const parsed = JSON.parse(raw) as Record<string, string[]>;
        initialReferencedCluesRef.current = parsed;
      }
    } catch {
      // ignore malformed cache
    }
  }, [teamInfo.teamUsername]);

  useEffect(() => {
    const fallbackSlug =
      banners[0]?.slug ??
      (state.meta?.state === "unlocked" ? "meta" : "hourlies");

    if (
      !selectedBannerSlug ||
      !availableBannerSlugs.includes(selectedBannerSlug)
    ) {
      if (fallbackSlug) {
        setSelectedBannerSlug(fallbackSlug);
        updateQueryParam(GACHA_QUERY_KEYS.BANNER, fallbackSlug, true);
      }
      return;
    }

    updateQueryParam(GACHA_QUERY_KEYS.BANNER, selectedBannerSlug, true);
  }, [selectedBannerSlug, availableBannerSlugs, banners, state.meta?.state]);

  useEffect(() => {
    const updatedQuestSlugs = new Set<string>();
    Object.entries(referencedClues).forEach(([questSlug, now]) => {
      const prev = initialReferencedCluesRef.current[questSlug] || [];
      if (prev.length !== now.length || prev.some((c, i) => c !== now[i])) {
        updatedQuestSlugs.add(questSlug);
      }
    });
    if (updatedQuestSlugs.size > 0) {
      setQuestUpdates((prev) => new Set([...prev, ...updatedQuestSlugs]));
    }
  }, [referencedClues]);

  useEffect(() => {
    if (questSlugsChanged) {
      if (currentQuestSlugs.length > 0) {
        setSelectedQuestSlug(currentQuestSlugs[0]);
      } else {
        setSelectedQuestSlug(undefined);
      }
    }
  }, [questSlugsChanged, currentQuestSlugs]);

  useEffect(() => {
    if (currentQuest) {
      setGuesses(currentQuest.guesses ?? []);
    }
  }, [currentQuest]);

  useEffect(() => {
    setLocalGuessInput("");
    setLocalGuessError(null);
  }, [selectedBannerSlug, selectedQuestSlug]);

  useEffect(() => {
    if (!IS_STATIC_SITE || !state.quests) return;
    const nextHourlyInputs: Record<string, string> = {};
    state.quests
      .filter((quest) => quest.banner_slug === "hourlies")
      .forEach((quest) => {
        if (quest.guesses.length > 0) {
          nextHourlyInputs[quest.quest_slug] = quest.guesses[0].canonical_input;
        }
      });
    setHourlyInput(nextHourlyInputs);
  }, [state.quests]);

  const selectedQuestReferencedClues = useMemo(() => {
    const clues = selectedQuestSlug
      ? referencedClues[selectedQuestSlug]
      : undefined;
    return clues ? clues.sort().join(",") : null;
  }, [selectedQuestSlug, referencedClues]);

  const isQuestCopyable = useMemo(() => {
    if (!selectedQuestSlug) {
      return false;
    }
    if (
      questContentCopyableMap &&
      selectedQuestSlug in questContentCopyableMap
    ) {
      return questContentCopyableMap[selectedQuestSlug] ?? false;
    }
    const html = questContentMap?.[selectedQuestSlug] ?? "";
    return !html.includes('data-quest-copyable="false"');
  }, [questContentCopyableMap, questContentMap, selectedQuestSlug]);

  useEffect(() => {
    if (!selectedQuestSlug) {
      setQuestContent(null);
      return;
    }

    setLoadingQuestContent(true);

    if (questContentNodeMap?.[selectedQuestSlug]) {
      setQuestContent(questContentNodeMap[selectedQuestSlug] ?? null);
    } else if (questContentMap?.[selectedQuestSlug]) {
      setQuestContent(
        <div
          className="prose max-w-none"
          dangerouslySetInnerHTML={{
            __html: questContentMap[selectedQuestSlug],
          }}
        />,
      );
    } else {
      // Show error if pre-rendered content not available
      setQuestContent(
        <div className="text-center text-red-500 p-4">
          Quest content not available. Please refresh the page.
        </div>,
      );
    }

    setLoadingQuestContent(false);
  }, [
    questContentMap,
    questContentNodeMap,
    selectedQuestReferencedClues,
    selectedQuestSlug,
  ]);

  const isHourlyCompletedByTeam = useMemo(() => {
    const isEligible =
      selectedBannerSlug === "hourlies"
        ? !currentQuest?.answer &&
          currentQuest?.quest_slug &&
          !hourlyInput[currentQuest.quest_slug]
        : guesses.filter((guess) => guess.status === "correct").length === 0;
    const teamCompleted = currentQuest?.solved;
    const userSubmitted = hourlyInput[currentQuest?.quest_slug ?? ""] ?? "";

    return (
      isEligible &&
      selectedBannerSlug === "hourlies" &&
      teamCompleted &&
      !userSubmitted
    );
  }, [
    currentQuest?.answer,
    currentQuest?.quest_slug,
    currentQuest?.solved,
    guesses,
    hourlyInput,
    selectedBannerSlug,
  ]);

  const questRewardPulls = useMemo(() => {
    const defaultReward =
      selectedBannerSlug === "hourlies"
        ? HOURLIES_PULL_GAINS
        : KNOWLEDGE_CHECKS_PULL_GAINS;
    return currentQuest?.reward_pulls ?? defaultReward;
  }, [currentQuest, selectedBannerSlug]);

  const rewardAmount = useMemo(() => {
    if (selectedBannerSlug === "hourlies" && isHourlyCompletedByTeam) {
      return 0;
    }
    return questRewardPulls * PULL_COST_MULTIPLIER;
  }, [isHourlyCompletedByTeam, questRewardPulls, selectedBannerSlug]);

  const parsedLocalPullCount = useMemo(() => {
    const parsed = parseInt(localPullInput, 10);
    return Number.isFinite(parsed) ? parsed : 0;
  }, [localPullInput]);

  const rateLimitStorageKey = useMemo(() => {
    return `fates_thread_casino_rate_limits_${teamInfo.teamUsername}`;
  }, [teamInfo.teamUsername]);

  const currentQuestRateLimitUntil = selectedQuestSlug
    ? rateLimitUntilByQuest[selectedQuestSlug]
    : undefined;
  const isRateLimited =
    typeof currentQuestRateLimitUntil === "number" &&
    currentQuestRateLimitUntil > Date.now();

  const scheduleRateLimitTimeout = useCallback(
    (questSlug: string, until: number) => {
      if (typeof window === "undefined") return;
      if (until <= Date.now()) return;
      const existingTimeout = rateLimitTimeoutsRef.current.get(questSlug);
      if (existingTimeout !== undefined) {
        window.clearTimeout(existingTimeout);
      }
      const timeoutId = window.setTimeout(
        () => {
          setRateLimitUntilByQuest((prev) => {
            if (prev[questSlug] !== until) {
              return prev;
            }
            const { [questSlug]: _removed, ...next } = prev;
            return next;
          });
          rateLimitTimeoutsRef.current.delete(questSlug);
        },
        Math.max(0, until - Date.now()),
      );
      rateLimitTimeoutsRef.current.set(questSlug, timeoutId);
    },
    [],
  );

  useEffect(() => {
    const timeouts = rateLimitTimeoutsRef.current;
    return () => {
      timeouts.forEach((timeoutId) => {
        window.clearTimeout(timeoutId);
      });
    };
  }, []);

  useEffect(() => {
    if (typeof window === "undefined") return;
    try {
      const raw = localStorage.getItem(rateLimitStorageKey);
      if (!raw) {
        setRateLimitUntilByQuest({});
        return;
      }
      const parsed = JSON.parse(raw) as Record<string, number>;
      const now = Date.now();
      const next: Record<string, number> = {};
      Object.entries(parsed).forEach(([questSlug, until]) => {
        if (typeof until === "number" && until > now) {
          next[questSlug] = until;
          scheduleRateLimitTimeout(questSlug, until);
        }
      });
      setRateLimitUntilByQuest(next);
    } catch {
      setRateLimitUntilByQuest({});
    }
  }, [rateLimitStorageKey, scheduleRateLimitTimeout]);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const now = Date.now();
    const filtered = Object.fromEntries(
      Object.entries(rateLimitUntilByQuest).filter(
        ([, until]) => typeof until === "number" && until > now,
      ),
    );
    try {
      localStorage.setItem(rateLimitStorageKey, JSON.stringify(filtered));
    } catch {
      // ignore storage failures
    }
  }, [rateLimitStorageKey, rateLimitUntilByQuest]);

  const setQuestRateLimit = (questSlug: string) => {
    const now = Date.now();
    const until = now + QUEST_RATE_LIMIT_MS;
    setRateLimitUntilByQuest((prev) => ({
      ...prev,
      [questSlug]: until,
    }));
    scheduleRateLimitTimeout(questSlug, until);
  };

  const resetRateLimits = () => {
    rateLimitTimeoutsRef.current.forEach((timeoutId) => {
      window.clearTimeout(timeoutId);
    });
    rateLimitTimeoutsRef.current.clear();
    setRateLimitUntilByQuest({});
    setLocalGuessError(null);
    if (typeof window !== "undefined") {
      try {
        localStorage.removeItem(rateLimitStorageKey);
      } catch {
        // ignore storage failures
      }
    }
  };

  const isDuplicateIncorrectGuess = (guess: string) => {
    if (!selectedQuestSlug || selectedBannerSlug === "hourlies") {
      return false;
    }
    const canonicalGuess = canonicalizeInput(guess);
    return guesses.some(
      (prev) =>
        prev.status === "incorrect" &&
        canonicalizeInput(prev.canonical_input) === canonicalGuess,
    );
  };

  const handleLocalGuessSubmit = async (
    event: React.FormEvent<HTMLFormElement>,
  ) => {
    event.preventDefault();
    if (!onLocalQuestSubmit || !selectedBannerSlug || !selectedQuestSlug) {
      return;
    }
    if (isRateLimited) {
      const untilLabel = currentQuestRateLimitUntil
        ? new Date(currentQuestRateLimitUntil).toLocaleTimeString()
        : "later";
      setLocalGuessError(
        `Please wait until ${untilLabel} before submitting again.`,
      );
      return;
    }
    const trimmed = localGuessInput.trim();
    if (!trimmed) {
      setLocalGuessError("Please enter a guess.");
      return;
    }
    if (isDuplicateIncorrectGuess(trimmed)) {
      setLocalGuessError("You already submitted that incorrect guess.");
      return;
    }
    setQuestRateLimit(selectedQuestSlug);
    setLocalGuessSubmitting(true);
    setLocalGuessError(null);
    try {
      const result = await onLocalQuestSubmit({
        bannerSlug: selectedBannerSlug,
        questSlug: selectedQuestSlug,
        guess: trimmed,
      });
      if (result?.error) {
        setLocalGuessError(result.error);
      } else {
        setLocalGuessInput("");
        if (
          selectedBannerSlug === "hourlies" &&
          selectedQuestSlug &&
          result?.canonicalInput
        ) {
          setHourlyInput((prev) => ({
            ...prev,
            [selectedQuestSlug]: result.canonicalInput ?? trimmed,
          }));
        }
      }
    } catch (error) {
      setLocalGuessError(String(error));
    }
    setLocalGuessSubmitting(false);
  };

  const sanitizedBannerForBackLink =
    selectedBannerSlug && selectedBannerSlug !== "meta"
      ? selectedBannerSlug
      : undefined;
  const backLinkHref =
    sanitizedBannerForBackLink && sanitizedBannerForBackLink !== "hourlies"
      ? `/rounds/fates_thread_casino?${GACHA_QUERY_KEYS.BANNER}=${sanitizedBannerForBackLink}`
      : "/rounds/fates_thread_casino";

  return (
    <TeamStateProvider teamState={teamState}>
      <div className="flex h-screen" style={CASINO_BACKGROUND_STYLE}>
        <div className="flex flex-col w-full h-full max-w-[70%] min-w-[1000px] mx-auto pt-16 px-8">
          {/* Back button */}
          <div className="flex items-center justify-between w-full pt-12 pb-2">
            <div className="flex gap-4">
              <GachaBackButton href={backLinkHref} />
              <GachaActionLink
                href={
                  selectedBannerSlug !== "hourlies"
                    ? `/rounds/fates_thread_casino/gallery?${GACHA_QUERY_KEYS.BANNER}=${selectedBannerSlug}`
                    : "/rounds/fates_thread_casino/gallery"
                }
                className="text-sm w-fit px-4 h-[42px]"
                variant="gold"
              >
                Gallery
              </GachaActionLink>
            </div>
            <PullInfo numChips={numChips} />
          </div>

          <GachaTutorial queryParams={queryParams} />
          {/* Topbar */}
          <GachaTopbar
            banners={banners}
            selectedBanner={selectedBannerSlug || null}
            onBannerSelect={setSelectedBannerSlug}
            meta={state.meta}
          />

          <div className="flex flex-1 min-h-0 gap-4 pb-8 min-w-0">
            {/* Sidebar */}
            <div className="w-full bg-white/80 rounded-lg p-4 overflow-y-auto max-w-80 min-w-80">
              {selectedBannerSlug === "hourlies" &&
                (IS_STATIC_SITE ? (
                  <div className="mb-4 rounded-lg border border-neutral-300 bg-white/90 p-3">
                    <div className="text-sm font-semibold text-neutral-700 mb-2">
                      Local Controls
                    </div>
                    <div className="flex items-center gap-2 mb-3">
                      <input
                        type="number"
                        min={1}
                        value={localPullInput}
                        onChange={(event) => {
                          setLocalPullInput(event.target.value);
                        }}
                        className="w-20 rounded border border-neutral-300 bg-white px-2 py-1 text-sm text-neutral-900 placeholder:text-neutral-500"
                        aria-label="Number of pulls to add"
                      />
                      <GachaActionButton
                        variant="green"
                        className="w-full py-1 px-4 text-base"
                        disabledMessage={
                          onAddPulls && parsedLocalPullCount > 0
                            ? undefined
                            : "Enter a pull count"
                        }
                        onClick={() => {
                          if (onAddPulls && parsedLocalPullCount > 0) {
                            onAddPulls(parsedLocalPullCount);
                          }
                        }}
                      >
                        Add Pulls
                      </GachaActionButton>
                    </div>
                    <GachaActionButton
                      variant="red"
                      className="w-full py-1 text-base"
                      onClick={() => {
                        resetRateLimits();
                        onResetRound?.();
                      }}
                    >
                      Reset Round
                    </GachaActionButton>
                  </div>
                ) : (
                  <GachaCountdown targetTime={nextQuestUnlockTime} />
                ))}
              {currentQuests.length === 0 ? (
                <div className="text-gray-600">No quests available</div>
              ) : (
                <div className="space-y-3">
                  {currentQuests.map((quest, index) => {
                    const questNumber = (() => {
                      const parts = quest.quest_slug.split("-");
                      const lastPart = parts[parts.length - 1];
                      const number = parseInt(lastPart);
                      return !isNaN(number) ? number + 1 : index + 1;
                    })();

                    return (
                      <button
                        key={quest.quest_slug}
                        type="button"
                        className={cn(
                          "relative w-full text-left p-3 rounded-lg border-2 border-neutral-300 bg-white h-[76px] flex flex-col",
                          quest.solved && "bg-[#D5F9C9] border-green-600",
                          selectedQuestSlug === quest.quest_slug
                            ? `${YELLOW_GRADIENT_STYLING} border-[#FEE187] shadow-md text-black`
                            : "hover:brightness-75 text-neutral-500",
                        )}
                        onClick={() => {
                          setSelectedQuestSlug(quest.quest_slug);
                          // Clear the update status when quest is selected
                          setQuestUpdates((prev) => {
                            const newSet = new Set(prev);
                            newSet.delete(quest.quest_slug);
                            return newSet;
                          });
                          // Persist only this quest's referenced_clues after user views it
                          try {
                            const storageKey = `fates_thread_casino_referenced_clues_${teamInfo.teamUsername}`;
                            if (typeof window !== "undefined") {
                              const raw = localStorage.getItem(storageKey);
                              const existing = raw
                                ? (JSON.parse(raw) as Record<string, string[]>)
                                : {};
                              const updated = {
                                ...existing,
                                [quest.quest_slug]:
                                  quest.referenced_clues || [],
                              };
                              localStorage.setItem(
                                storageKey,
                                JSON.stringify(updated),
                              );
                              // reflect this focused update in memory as well
                              initialReferencedCluesRef.current[
                                quest.quest_slug
                              ] = quest.referenced_clues || [];
                            }
                          } catch {
                            // ignore storage errors
                          }
                        }}
                      >
                        <ExclamationMark
                          aria-label="This quest has an update"
                          className={cn(
                            "absolute fill-red-800 -top-2 -left-2 w-5 h-[35px]",
                            questUpdates.has(quest.quest_slug)
                              ? "opacity-100"
                              : "opacity-0",
                          )}
                        />
                        <div className="flex w-full items-center justify-between mb-1">
                          <span className="font-medium flex items-center gap-2">
                            Quest {questNumber}
                            <ErratumIcon
                              resource={{
                                type: "quest",
                                slug: quest.quest_slug,
                              }}
                              iconClassName="h-4 w-4"
                            />
                          </span>
                          <span
                            className={cn(
                              "px-2 py-1 text-xs rounded-full",
                              quest.solved
                                ? "bg-green-600 text-white"
                                : "bg-gray-500 text-white",
                            )}
                          >
                            {quest.solved ? "Solved" : "Unsolved"}
                          </span>
                        </div>

                        <div className="text-sm text-gray-700">
                          {selectedBannerSlug !== "hourlies" &&
                            quest.solved &&
                            quest.answer && <>Answer: {quest.answer}</>}
                          {selectedBannerSlug === "hourlies" &&
                            hourlyInput[quest.quest_slug] && (
                              <>You answered {hourlyInput[quest.quest_slug]}</>
                            )}
                        </div>
                      </button>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Quest content area */}
            <div className="flex-1 bg-white/80 rounded-lg p-4 text-black flex flex-col min-w-0">
              {/* Scrollable section */}
              <div className="flex-1 overflow-y-auto flex flex-col min-w-0">
                <div className="flex-1 flex flex-col">
                  {!selectedQuestSlug ? (
                    <div className="flex-1 flex items-center justify-center text-gray-500 p-8">
                      Select a quest from the sidebar to view its content
                    </div>
                  ) : loadingQuestContent ? (
                    <div className="flex-1 flex items-center justify-center text-gray-600 p-8">
                      Loading quest content...
                    </div>
                  ) : questContent ? (
                    <div className="flex-1 relative min-h-20">
                      {questContent}
                      {isQuestCopyable && (
                        <CopyToClipboard
                          variant="custom"
                          className="absolute bottom-2 right-0"
                          contentId="quest"
                          iconClassName="text-5xl"
                          tooltipBeforeCopy="Click to copy quest content for ease of pasting into Google Sheets or Excel."
                        />
                      )}
                    </div>
                  ) : (
                    <div className="flex-1 flex items-center justify-center text-gray-500 p-8">
                      No content available for this quest
                    </div>
                  )}

                  {selectedBannerSlug === "hourlies" &&
                    selectedQuestSlug &&
                    // Check if it has been completed by the solver or any of their team members.
                    (hourlyInput[selectedQuestSlug] ||
                      isHourlyCompletedByTeam) && (
                      <>
                        <div className="border-t border-black h-px my-4"></div>
                        <div className="flex flex-col items-center mb-4">
                          <span className="text-lg font-semibold mb-4">
                            Most common answers
                          </span>
                          {topGuessPercentages?.[selectedQuestSlug] ? (
                            <TopGuessesPie
                              slices={
                                topGuessPercentages[selectedQuestSlug] as {
                                  input: string;
                                  percentage: number;
                                }[]
                              }
                            />
                          ) : (
                            <div className="text-center text-gray-500 py-4">
                              Not enough responses yet, please check back later.
                            </div>
                          )}
                        </div>
                      </>
                    )}

                  {selectedBannerSlug !== "hourlies" && (
                    <>
                      <div className="border-t border-black h-px my-4"></div>
                      <div className="flex flex-col pb-2">
                        <span className="text-lg font-semibold mb-2">
                          Previous Guesses:
                        </span>
                        <div className="space-y-1">
                          {guesses.length > 0 ? (
                            guesses.map((guess, index) => (
                              <div
                                key={index}
                                className={cn(
                                  "px-2 py-1 rounded border text-sm flex items-center justify-between w-full min-w-0",
                                  guess.status === "correct"
                                    ? "bg-green-100 border-green-300 text-green-800"
                                    : guess.status === "incorrect"
                                      ? "bg-red-100 border-red-300 text-red-800"
                                      : "bg-yellow-100 border-yellow-300 text-yellow-800",
                                )}
                              >
                                <span
                                  className="font-mono min-w-0 flex-1 truncate"
                                  title={guess.canonical_input}
                                >
                                  {guess.canonical_input}
                                </span>

                                <span className="text-xs flex-shrink-0 ml-2">
                                  {guess.status} •{" "}
                                  {new Date(guess.timestamp).toLocaleString()}
                                </span>
                              </div>
                            ))
                          ) : (
                            <div className="text-gray-500 text-center text-sm">
                              No previous guesses
                            </div>
                          )}
                        </div>
                      </div>
                    </>
                  )}
                </div>
              </div>

              {/* Footer */}
              <div className="shrink-0 border-t border-black mt-2 pt-4 pl-2 flex">
                {(
                  selectedBannerSlug === "hourlies"
                    ? !currentQuest?.answer &&
                      currentQuest?.quest_slug &&
                      !hourlyInput[currentQuest.quest_slug]
                    : currentQuest?.quest_slug &&
                      guesses.filter((guess) => guess.status === "correct")
                        .length === 0
                ) ? (
                  <div className="flex flex-col w-full">
                    <div className="flex justify-between gap-4">
                      <div className="flex items-center text-2xl">
                        Rewards:
                        <img src={casino_chip} alt="Casino Chip" width={44} />×
                        {rewardAmount}
                      </div>
                      <div className="flex items-center max-w-80 w-full justify-end gap-2">
                        {IS_STATIC_SITE ? (
                          <form
                            onSubmit={(event) => {
                              void handleLocalGuessSubmit(event);
                            }}
                            className="flex flex-col w-full items-end"
                          >
                            <div className="relative flex w-full max-w-80 items-center justify-end">
                              <PrimarySearchField
                                id="gacha-quest-guess"
                                name="guess"
                                type="text"
                                value={localGuessInput}
                                onChange={(event) => {
                                  setLocalGuessInput(event.target.value);
                                  if (localGuessError) {
                                    setLocalGuessError(null);
                                  }
                                }}
                                placeholder={
                                  localGuessSubmitting
                                    ? "Submitting..."
                                    : "Submit guess here..."
                                }
                                disabled={
                                  localGuessSubmitting || !onLocalQuestSubmit
                                }
                                required
                                buttonProps={{
                                  type: "submit",
                                  disabled:
                                    localGuessSubmitting ||
                                    !localGuessInput.trim() ||
                                    !onLocalQuestSubmit,
                                  "aria-label": "Submit guess",
                                }}
                              />
                            </div>
                            {localGuessError && (
                              <div className="text-sm text-red-600 mt-1">
                                {localGuessError}
                              </div>
                            )}
                          </form>
                        ) : (
                          <SubpuzzleGuessSection
                            key={`${selectedBannerSlug}-${selectedQuestSlug}`}
                            slug={`fates_thread_casino/${selectedBannerSlug}/${selectedQuestSlug}`}
                            guesses={[]} // do not use subpuzzle guesses
                            onGuessesUpdate={(guesses) => {
                              const correctGuesses = guesses.filter(
                                (guess) => guess.status === "correct",
                              );

                              if (
                                selectedBannerSlug === "hourlies" &&
                                selectedQuestSlug &&
                                correctGuesses.length > 0
                              ) {
                                setHourlyInput((prevHourlyInput) => ({
                                  ...prevHourlyInput,
                                  [selectedQuestSlug]:
                                    correctGuesses[0].canonical_input,
                                }));
                              }
                            }}
                            className="bg-transparent p-0 w-full"
                            errorMessageClassName="text-sm"
                            rateLimitMessageClassName="text-sm"
                            inputContainerClassName="justify-end"
                          />
                        )}
                      </div>
                    </div>

                    {isHourlyCompletedByTeam && (
                      <div className="text-sm text-gray-600 pt-1">
                        Your team has already received the rewards for this
                        hourly, but you can still submit an answer for fun.
                      </div>
                    )}
                  </div>
                ) : (
                  <div className="flex w-full h-[58px] items-center text-xl">
                    {selectedBannerSlug === "hourlies"
                      ? "You have already completed this hourly. Refresh to see newest global stats."
                      : "You have solved this quest."}
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </TeamStateProvider>
  );
};

export default GachaQuests;
