import React, { useEffect, useState } from "react";

type CountdownTimerProps = {
  targetTime: Date | undefined;
};

const GachaCountdown = ({ targetTime }: CountdownTimerProps) => {
  const [timeLeft, setTimeLeft] = useState<{
    hours: number;
    minutes: number;
    seconds: number;
  }>({ hours: 0, minutes: 0, seconds: 0 });

  useEffect(() => {
    if (!targetTime) return;

    const updateTimer = () => {
      const now = new Date().getTime();
      const target = targetTime.getTime();
      const difference = target - now;

      if (difference > 0) {
        const hours = Math.floor(difference / (1000 * 60 * 60));
        const minutes = Math.floor(
          (difference % (1000 * 60 * 60)) / (1000 * 60),
        );
        const seconds = Math.floor((difference % (1000 * 60)) / 1000);
        setTimeLeft({ hours, minutes, seconds });
      } else {
        setTimeLeft({ hours: 0, minutes: 0, seconds: 0 });
      }
    };

    updateTimer();
    const interval = setInterval(updateTimer, 1000);

    return () => {
      clearInterval(interval);
    };
  }, [targetTime]);

  if (!targetTime) return null;

  return (
    <div className="text-black bg-blue-100 border border-blue-300 rounded-lg p-3 mb-4">
      <div className="text-center">
        <div className="text-sm font-medium text-blue-800 mb-2">
          Next Hourlies Unlocks In:
        </div>
        <div className="flex justify-center space-x-2 text-lg font-bold text-blue-900">
          <div className="bg-blue-200 rounded px-2 py-1 min-w-[3rem]">
            {timeLeft.hours.toString().padStart(2, "0")}
          </div>
          <span className="text-blue-600">:</span>
          <div className="bg-blue-200 rounded px-2 py-1 min-w-[3rem]">
            {timeLeft.minutes.toString().padStart(2, "0")}
          </div>
          <span className="text-blue-600">:</span>
          <div className="bg-blue-200 rounded px-2 py-1 min-w-[3rem]">
            {timeLeft.seconds.toString().padStart(2, "0")}
          </div>
        </div>
        <div className="flex justify-center space-x-4 mt-2 text-xs text-blue-700 gap-2">
          <span>Hours</span>
          <span>Minutes</span>
          <span>Seconds</span>
        </div>
      </div>
    </div>
  );
};

export default GachaCountdown;
