import {
  type TeamHuntState,
  type TeamInfo,
  type SubpuzzleState,
} from "@hunt/public-client";
import { getSubpuzzlesForTeam } from "@hunt/puzzles";
import React, { useCallback, useEffect, useMemo, useState } from "react";
import { hydrateRoot } from "react-dom/client";
import { useSolvedPuzzlesState } from "../components/puzzleSolveLocalState";
import GachaQuests from "../rounds/dimensions/gacha/GachaQuests";
import { mergeCasinoState } from "../rounds/dimensions/gacha/clientUtils";
import { STATIC_HOURLIES_TOP_GUESSES } from "../rounds/dimensions/gacha/gachaHourliesResults";
import {
  addLocalPullsGetAndSet,
  applyGachaQuestGuessGetAndSet,
  buildLocalCasinoState,
  buildLocalTeamState,
  getHydratedGachaLog,
  resetGachaLocalState,
} from "../rounds/dimensions/gacha/gachaLocalState";
import type { CasinoStateWithUI } from "../rounds/dimensions/gacha/types";
import { useGachaLocalState } from "../rounds/dimensions/gacha/useGachaLocalState";
import { IS_STATIC_SITE } from "../utils/staticSite";
import { ErrataDataProvider } from "./ErrataProvider";
import useDataset from "./useDataset";

const GachaQuestManager = ({
  initialCasinoState,
  initialTeamState,
  initialTeamInfo,
  nextQuestUnlockTime,
  topGuessPercentages,
  queryParams,
  initialQuestContentMap,
}: {
  initialCasinoState: CasinoStateWithUI;
  initialTeamState: TeamHuntState;
  initialTeamInfo: TeamInfo;
  nextQuestUnlockTime: Date | undefined;
  topGuessPercentages: Record<
    string,
    { input: string; percentage: number }[] | undefined
  >;
  queryParams: URLSearchParams;
  initialQuestContentMap?: Record<string, string>;
}) => {
  const isStaticSite = IS_STATIC_SITE;
  // Use websocket data for real-time updates
  const teamState = useDataset("team_state", undefined, initialTeamState);
  const wsState = useDataset("fates_thread_casino", undefined, {
    epoch: initialCasinoState.epoch,
    available_pulls: initialCasinoState.available_pulls,
    num_solves: initialCasinoState.num_solves,
    banner_progress: initialCasinoState.banner_progress,
  });

  const [state, setState] = useState<CasinoStateWithUI>(initialCasinoState);
  const [questContentMap, setQuestContentMap] = useState<
    Record<string, string>
  >(initialQuestContentMap || {});
  const { solvedMap } = useSolvedPuzzlesState();
  const { localState, setLocalState } = useGachaLocalState();

  useEffect(() => {
    if (isStaticSite) return;
    if (wsState && typeof wsState === "object" && "epoch" in wsState) {
      setState((currentState) => mergeCasinoState(wsState, currentState));

      if ("questContentMap" in wsState && wsState.questContentMap) {
        setQuestContentMap((current) => ({
          ...current,
          ...(wsState.questContentMap as Record<string, string>),
        }));
      }
    }
  }, [isStaticSite, wsState]);

  useEffect(() => {
    if (!isStaticSite || !localState) return;
    const nextState = buildLocalCasinoState({
      teamState,
      localState,
      solvedMap,
    });
    setState(nextState);
  }, [isStaticSite, localState, solvedMap, teamState]);

  const gachaActivityLog = useMemo(
    () => (localState ? getHydratedGachaLog(localState) : []),
    [localState],
  );

  const { questContentNodeMap, questContentCopyableMap } = useMemo(() => {
    if (!isStaticSite || !localState) {
      return {
        questContentNodeMap: undefined,
        questContentCopyableMap: undefined,
      };
    }
    const patchedTeamState = buildLocalTeamState({
      teamState,
      localState,
      solvedMap,
    });
    const subpuzzles = getSubpuzzlesForTeam(patchedTeamState, gachaActivityLog);
    const dummyState: SubpuzzleState = { guesses: [] };
    const nodeMap: Record<string, React.ReactNode> = {};
    const copyableMap: Record<string, boolean> = {};

    (state.quests ?? []).forEach((quest) => {
      const subpuzzle = subpuzzles[quest.quest_slug];
      if (!subpuzzle?.content?.component) {
        return;
      }
      const ContentComponent = subpuzzle.content.component;
      const contentNode = (
        <ContentComponent
          type="subpuzzle"
          teamState={patchedTeamState}
          subpuzzleState={dummyState}
          query={{}}
          gachaActivityLog={gachaActivityLog}
        />
      );
      const isCopyable = subpuzzle.content.copyable !== false;
      copyableMap[quest.quest_slug] = isCopyable;
      nodeMap[quest.quest_slug] = isCopyable ? (
        contentNode
      ) : (
        <div data-quest-copyable="false">{contentNode}</div>
      );
    });

    return {
      questContentNodeMap: nodeMap,
      questContentCopyableMap: copyableMap,
    };
  }, [
    gachaActivityLog,
    isStaticSite,
    localState,
    solvedMap,
    state.quests,
    teamState,
  ]);

  const handleLocalQuestSubmit = useCallback(
    async ({
      bannerSlug,
      questSlug,
      guess,
    }: {
      bannerSlug: string;
      questSlug: string;
      guess: string;
    }) => {
      const { nextState, error, canonicalInput, solved } =
        await applyGachaQuestGuessGetAndSet({
          bannerSlug,
          questSlug,
          guess,
        });
      if (error) {
        return { error };
      }
      setLocalState(nextState);
      const nextUiState = buildLocalCasinoState({
        teamState,
        localState: nextState,
        solvedMap,
      });
      setState(nextUiState);
      return { canonicalInput, solved };
    },
    [setLocalState, solvedMap, teamState],
  );

  const handleAddPulls = useCallback(
    (pullCount: number) => {
      if (pullCount <= 0) return;
      void (async () => {
        const nextState = await addLocalPullsGetAndSet(pullCount);
        setLocalState(nextState);
        const nextUiState = buildLocalCasinoState({
          teamState,
          localState: nextState,
          solvedMap,
        });
        setState(nextUiState);
      })();
    },
    [setLocalState, solvedMap, teamState],
  );

  const handleResetRound = useCallback(() => {
    void (async () => {
      const resetState = await resetGachaLocalState();
      setLocalState(resetState);
      const nextUiState = buildLocalCasinoState({
        teamState,
        localState: resetState,
        solvedMap,
      });
      setState(nextUiState);
    })();
  }, [setLocalState, solvedMap, teamState]);

  const numChips = state.available_pulls ?? 0;
  const effectiveTopGuessPercentages = isStaticSite
    ? STATIC_HOURLIES_TOP_GUESSES
    : topGuessPercentages;

  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <GachaQuests
        state={state}
        teamState={teamState}
        teamInfo={initialTeamInfo}
        queryParams={queryParams}
        numChips={numChips}
        nextQuestUnlockTime={nextQuestUnlockTime}
        topGuessPercentages={effectiveTopGuessPercentages}
        questContentMap={questContentMap}
        questContentNodeMap={questContentNodeMap}
        questContentCopyableMap={questContentCopyableMap}
        onLocalQuestSubmit={isStaticSite ? handleLocalQuestSubmit : undefined}
        onAddPulls={isStaticSite ? handleAddPulls : undefined}
        onResetRound={isStaticSite ? handleResetRound : undefined}
      />
    </ErrataDataProvider>
  );
};

const elem = document.getElementById("fates-thread-casino-quests-root");
if (elem) {
  const {
    initialTeamState: teamState,
    initialTeamInfo: teamInfo,
    initialCasinoState: fatesThreadCasinoState,
    nextQuestUnlockTimeRaw: nextQuestUnlockTimeRaw,
    topGuessPercentages: topGuessPercentages,
    questContentMap: questContentMap,
  } = window as unknown as {
    initialTeamState: TeamHuntState;
    initialTeamInfo: TeamInfo;
    initialCasinoState: CasinoStateWithUI;
    nextQuestUnlockTimeRaw: string;
    topGuessPercentages: Record<
      string,
      { input: string; percentage: number }[]
    >;
    questContentMap?: Record<string, string>;
  };
  const queryParams = new URLSearchParams(window.location.search);
  let nextQuestUnlockTime: Date | undefined = undefined;
  if (
    typeof nextQuestUnlockTimeRaw === "string" &&
    nextQuestUnlockTimeRaw.trim() !== ""
  ) {
    const parsedDate = new Date(nextQuestUnlockTimeRaw);
    if (!isNaN(parsedDate.getTime())) {
      nextQuestUnlockTime = parsedDate;
    }
  }

  hydrateRoot(
    elem,
    <GachaQuestManager
      initialCasinoState={fatesThreadCasinoState}
      initialTeamState={teamState}
      initialTeamInfo={teamInfo}
      nextQuestUnlockTime={nextQuestUnlockTime}
      topGuessPercentages={topGuessPercentages}
      queryParams={queryParams}
      initialQuestContentMap={questContentMap}
    />,
  );
} else {
  console.error(
    "Could not mount Fate's Thread Casino Quest because #fates-thread-casino-quests-root was nowhere to be found",
  );
}
