import React from "react";

type Slice = { input: string; percentage: number };

function polarToCartesian(
  centerX: number,
  centerY: number,
  radius: number,
  angleInDegrees: number,
) {
  const angleInRadians = ((angleInDegrees - 90) * Math.PI) / 180.0;
  return {
    x: centerX + radius * Math.cos(angleInRadians),
    y: centerY + radius * Math.sin(angleInRadians),
  };
}

function describeArc(
  x: number,
  y: number,
  radius: number,
  startAngle: number,
  endAngle: number,
) {
  const start = polarToCartesian(x, y, radius, endAngle);
  const end = polarToCartesian(x, y, radius, startAngle);
  const largeArcFlag = endAngle - startAngle <= 180 ? "0" : "1";
  return [
    "M",
    x,
    y,
    "L",
    start.x,
    start.y,
    "A",
    radius,
    radius,
    0,
    largeArcFlag,
    0,
    end.x,
    end.y,
    "Z",
  ].join(" ");
}

const COLORS = [
  "#be9d29", // gold
  "#ab371d", // red
  "#2563eb", // blue-600
  "#16a34a", // green-600
  "#ea580c", // orange-600
  "#475569", // slate-600
];

export default function TopGuessesPie({
  slices,
  size = 160,
  strokeWidth = 0,
}: {
  slices: Slice[];
  size?: number;
  strokeWidth?: number;
}) {
  if (slices?.length === 0) return null;

  const total = slices.reduce((acc, s) => acc + Math.max(0, s.percentage), 0);
  const data = total > 0 ? slices.filter((s) => s.percentage > 0) : [];

  const radius = size / 2 - strokeWidth / 2;
  const center = size / 2;

  let currentAngle = 0;
  const EPS = 0.0001;
  const paths = data.map((slice, idx) => {
    const fraction = Math.max(0, slice.percentage) / 100;
    const angle = fraction * 360;
    const startAngle = currentAngle;
    const endAngle = currentAngle + angle;
    currentAngle = endAngle;
    const color = COLORS[idx % COLORS.length];
    // Full-circle special case (e.g., 100%)
    if (fraction >= 1 - EPS) {
      return (
        <circle key={idx} cx={center} cy={center} r={radius} fill={color} />
      );
    }
    // Zero-size slice: skip
    if (fraction <= EPS) {
      return null;
    }
    const d = describeArc(center, center, radius, startAngle, endAngle);
    return <path key={idx} d={d} fill={color} />;
  });

  return (
    <div className="flex items-start gap-4">
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
        {paths}
      </svg>
      <div className="flex flex-col gap-1 text-sm min-w-[200px]">
        {data.map((s, idx) => (
          <div key={idx} className="flex items-center gap-2">
            <span
              className="inline-block w-3 h-3 rounded"
              style={{ backgroundColor: COLORS[idx % COLORS.length] }}
            />
            <span className="font-mono truncate flex-1 overflow-hidden">
              {s.input}
            </span>
            <span className="ml-auto text-gray-600 tabular-nums text-right">
              {s.percentage.toFixed(1)}%
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}
